import { getBattleActions, previewBattleAction, battleActorDisplayName } from './combat.js';
import { combatOutlook } from './combat-guidance.js';
import { renderCombatStatuses, renderEnemyPrediction } from './combat-status-ui.js';
import { renderEnemyPortrait } from './enemies.js';
import { resistanceReadout } from './combat-rules.js';
import { curseCombatNote } from './curses.js';

/** Shared pure read model. Selection defaults never write to a life or UI. */
export function buildBattleReadModel(b, { selectedEnemy = null, selectedAlly = null, commandsEnabled = !b.outcome, outlookEnabled = true } = {}) {
  const actorName = a => battleActorDisplayName(a, b), actor = b.actors.find(a => a.id === b.currentActorId);
  const enemies = b.actors.filter(a => a.side === 'enemy' && a.hp > 0), allies = b.actors.filter(a => a.side === 'party' && a.hp > 0);
  if (!enemies.some(a => a.id === selectedEnemy)) selectedEnemy = enemies[0]?.id || null;
  if (!allies.some(a => a.id === selectedAlly)) selectedAlly = actor?.side === 'party' ? actor.id : allies[0]?.id || null;
  const actions = getBattleActions(b).map(action => {
    const preview = previewBattleAction(b, action.id, action.targetSide === 'party' ? selectedAlly : selectedEnemy);
    return { ...action, preview, disabledReason: preview.legal ? null : preview.reason };
  });
  return { battle: b, actor, actorName, selectedEnemy, selectedAlly, actions, commandsEnabled, outlook: commandsEnabled && outlookEnabled ? combatOutlook(b) : null };
}

/** Same workspace for real encounters and isolated rehearsal. The caller owns
 * outcome text, party portraits, operation names and surrounding dialog. */
export function renderBattleWorkspace(model, ui, {
  actionOp = 'battle-action', enemyTargetName = 'battle-target', allyTargetName = 'battle-ally-target',
  idPrefix = 'battle', sessionId = null, portraitFor, commandHelpFor = () => '', outcomeContent = '', headerContent = '',
  eyebrow = 'ENCOUNTER', fieldLabel = 'Combatants and targets', commandsLabel = 'Battle commands',
  allySelectedLabel = 'Healing target', allyTargetLabel = 'Heal this ally', logLines = model.battle.log,
} = {}) {
  const { e, title, meter, chapter } = ui;
  const { battle: b, actor, actorName, actions, selectedEnemy, selectedAlly, commandsEnabled, outlook } = model;
  const token = sessionId ? ` data-practice-session="${e(sessionId)}"` : '';
  const actorCard = a => `<div class="actor-card ${a.side === 'enemy' ? 'enemy' : ''} ${a.id === b.currentActorId ? 'current' : ''} ${a.hp <= 0 ? 'defeated' : ''}"><div class="actor-heading">${a.side === 'enemy' ? renderEnemyPortrait({ ...a, name: actorName(a) }) : portraitFor(a)}<strong>${e(actorName(a))}</strong>${a.id === b.currentActorId ? '<span class="badge">Their turn</span>' : ''}</div>${renderCombatStatuses(a)}<p class="muted small-copy">${e(title(a.role))}${a.hp <= 0 ? ' · Down' : ''}</p>${meter(a.hp, a.maxHp, 'Health')}${a.maxMp ? meter(a.mp, a.maxMp, 'Focus', 'focus-meter') : ''}${a.side === 'party' && a.hp > 0 && commandsEnabled ? `<label class="target-label"><input type="radio" name="${e(allyTargetName)}" value="${e(a.id)}" ${selectedAlly === a.id ? 'checked' : ''}${token}> ${e(actorName(a))} · ${selectedAlly === a.id ? e(allySelectedLabel) : e(allyTargetLabel)}</label>` : ''}${(a.id === 'hero' || a.status?.inspected) && (a.condition || a.illustration?.condition) ? `<p class="small-copy" data-curse-combat>${e(curseCombatNote(a.condition || a.illustration.condition, a))}</p>` : ''}${a.status?.inspected ? `<p class="known-weakness">Read: ${a.weakness ? 'vulnerable to ' + e(a.weakness) : 'no elemental weakness'} · ${e(resistanceReadout(a))}</p>` : ''}${a.intent ? `<p class="muted small-copy">${e(a.intent)}</p>${renderEnemyPrediction(b, a, actorName)}` : ''}${a.side === 'enemy' && a.hp > 0 && commandsEnabled ? `<label class="target-label"><input type="radio" name="${e(enemyTargetName)}" value="${e(a.id)}" ${selectedEnemy === a.id ? 'checked' : ''}${token}> ${e(actorName(a))} · ${selectedEnemy === a.id ? 'Selected target' : 'Target'}</label>` : ''}</div>`;
  const order = `<div class="turn-order" aria-label="Turn order">${b.turnOrder.map(id => b.actors.find(a => a.id === id)).filter(a => a && a.hp > 0).map(a => `<span class="turn-chip ${a.id === b.currentActorId ? 'active' : ''}">${e(actorName(a))}</span>`).join('')}</div>`;
  const commands = !commandsEnabled ? outcomeContent : `<div class="section-heading"><div><span class="eyebrow">CHOOSE YOUR MOVE</span><h2>${e(actorName(actor))}</h2></div><span class="badge">${b.potions} remedies</span></div><p class="small-copy" data-preview-explanation>Command previews show the immediate result before turn effects and enemy replies. Choose an enemy or support target to compare.</p><div class="battle-actions">${actions.map(a => `<div class="battle-action-option"><button class="button ${a.id === 'attack' ? 'primary' : 'secondary'}" data-op="${e(actionOp)}" data-id="${e(a.id)}"${token} ${a.disabledReason ? 'disabled' : ''} aria-describedby="${e(idPrefix)}-preview-${e(a.id)}" title="${e(a.disabledReason || a.description)}">${e(a.label)}${a.cost && a.cost !== 'Free' ? ` · ${e(a.cost)}` : ''}</button><p class="small-copy action-preview" id="${e(idPrefix)}-preview-${e(a.id)}" data-action-preview="${e(a.id)}">${e(a.preview.summary)}</p></div>`).join('')}</div>${actions.filter(a => a.disabledReason).length ? `<details class="battle-barriers"><summary>Unavailable moves</summary>${actions.filter(a => a.disabledReason).map(a => `<p><strong>${e(a.label)}:</strong> ${e(a.disabledReason)}</p>`).join('')}</details>` : ''}<details class="battle-help"><summary>Abilities &amp; trait effects</summary>${actions.map(a => `<p class="small-copy"><strong>${e(a.label)}:</strong> ${e(a.disabledReason || a.description)}${commandHelpFor(a, actor)}</p>`).join('')}</details>`;
  return `<div class="battle-workspace"${token}><header class="battle-topline">${headerContent}${chapter(b.title, !commandsEnabled ? 'The encounter has ended.' : `Round ${b.round} · ${actorName(actor) || 'Your party'} has the next move.`, eyebrow)}${order}${commandsEnabled ? '<p class="small-copy" data-enemy-prediction-note>Enemy recipients are current predictions, not a promise of damage or a full-round forecast. Guarding, Health, Focus, marks and intervening actions can change them before an enemy acts.</p>' : ''}${outlook ? `<div class="combat-outlook" data-battle-outlook><strong>${e(outlook.summary)}</strong><details><summary>About this estimate</summary><p class="small-copy">${e(outlook.caveat)}</p></details></div>` : ''}</header><div class="battle-layout"><div class="battle-field" tabindex="0" role="region" aria-label="${e(fieldLabel)}"><div class="combat-grid"><section role="group" aria-label="Party and support targets"><div class="section-heading"><h3>Your party</h3></div>${b.actors.filter(a => a.side === 'party').map(actorCard).join('')}</section><section role="group" aria-label="Opponents and attack targets"><div class="section-heading"><h3>Opponents</h3></div>${b.actors.filter(a => a.side === 'enemy').map(actorCard).join('')}</section></div></div><section class="panel battle-command-panel" tabindex="0" role="region" aria-label="${e(commandsLabel)}">${commands}<div class="battle-recent-log" aria-live="polite">${logLines.slice(-3).map(line => `<p>${e(line)}</p>`).join('')}</div><details><summary>Battle record</summary><ol class="battle-log">${logLines.map(line => `<li>${e(line)}</li>`).join('')}</ol></details></section></div></div>`;
}
